body.script:
    // Initial State Parameters
    const state = {
      stemWidth: 9,
      rCurve: 16,
      rExt: 18,
      riGap: 8,
      leafScale: 1.1,
      leafY: -2,
      textColor: "#0F172A",
      leafColor: "#10B981",
      taglineSpacing: 3.5,
      taglineSize: 11,
      zoom: 2.2,
      isDarkInspect: false
    };

    // DOM Elements
    const stemWidthInput = document.getElementById('stem-width');
    const rCurveInput = document.getElementById('r-curve');
    const rExtInput = document.getElementById('r-ext');
    const riGapInput = document.getElementById('ri-gap');
    const leafScaleInput = document.getElementById('leaf-scale');
    const leafYInput = document.getElementById('leaf-y');
    const textColorInput = document.getElementById('text-color');
    const leafColorInput = document.getElementById('leaf-color');
    const taglineSpacingInput = document.getElementById('tagline-spacing');
    const taglineSizeInput = document.getElementById('tagline-size');

    const svgRenderContainer = document.getElementById('svg-render-container');
    const mobileHeaderLogo = document.getElementById('mobile-header-logo');
    const footerLogo = document.getElementById('footer-logo');
    const svgCodeOutput = document.getElementById('svg-code-output');
    const inspectorCanvas = document.getElementById('inspector-canvas');

    // Generate Dynamic SVG Vector String
    function generateSVGString(options = {}) {
      const textColor = options.textColor || state.textColor;
      const leafColor = options.leafColor || state.leafColor;
      const sw = state.stemWidth;
      const rCurve = state.rCurve;
      const rExt = state.rExt;
      const gap = state.riGap;
      const lScale = state.leafScale;
      const lY = state.leafY;
      const tSpacing = state.taglineSpacing;
      const tSize = state.taglineSize;

      // X coordinate dynamics
      const xN = 108;
      const xu1 = 154;
      const xt = 202;
      const xr = 224;
      const xi = xr + sw + gap;
      const xLeaf = xi + (sw / 2) - 4;
      const xD = xi + sw + 16;
      const xu2 = xD + 40;
      const xp = xu2 + 44;
      const xe = xp + 45;

      const totalWidth = xe + 35;

      return `












































  RESEARCH PLATFORM
`.trim();
    }

    // Update Live Renders across panels
    function updateRenders() {
      // Sync UI labels
      document.getElementById('stem-width-val').innerText = `${state.stemWidth}px`;
      document.getElementById('r-curve-val').innerText = `${state.rCurve}px`;
      document.getElementById('r-ext-val').innerText = `${state.rExt}px`;
      document.getElementById('ri-gap-val').innerText = `${state.riGap}px`;
      document.getElementById('leaf-scale-val').innerText = `${state.leafScale}x`;
      document.getElementById('leaf-y-val').innerText = `${state.leafY}px`;
      document.getElementById('text-color-hex').innerText = state.textColor.toUpperCase();
      document.getElementById('leaf-color-hex').innerText = state.leafColor.toUpperCase();
      document.getElementById('tagline-spacing-val').innerText = `${state.taglineSpacing}px`;
      document.getElementById('tagline-size-val').innerText = `${state.taglineSize}px`;
      document.getElementById('zoom-level-text').innerText = `${Math.round(state.zoom * 100)}%`;

      // 1. Inspector Render
      const mainSVG = generateSVGString();
      svgRenderContainer.innerHTML = mainSVG;
      svgRenderContainer.style.transform = `scale(${state.zoom})`;

      // 2. Mobile Header Render
      mobileHeaderLogo.innerHTML = generateSVGString({ textColor: "#0F172A" });

      // 3. Dark Footer Render
      footerLogo.innerHTML = generateSVGString({ textColor: "#F8FAFC" });

      // 4. Update Code Box
      svgCodeOutput.textContent = mainSVG;
    }

    // Event Listeners for Controls
    stemWidthInput.addEventListener('input', (e) => { state.stemWidth = parseFloat(e.target.value); updateRenders(); });
    rCurveInput.addEventListener('input', (e) => { state.rCurve = parseFloat(e.target.value); updateRenders(); });
    rExtInput.addEventListener('input', (e) => { state.rExt = parseFloat(e.target.value); updateRenders(); });
    riGapInput.addEventListener('input', (e) => { state.riGap = parseFloat(e.target.value); updateRenders(); });
    leafScaleInput.addEventListener('input', (e) => { state.leafScale = parseFloat(e.target.value); updateRenders(); });
    leafYInput.addEventListener('input', (e) => { state.leafY = parseFloat(e.target.value); updateRenders(); });
    textColorInput.addEventListener('input', (e) => { state.textColor = e.target.value; updateRenders(); });
    leafColorInput.addEventListener('input', (e) => { state.leafColor = e.target.value; updateRenders(); });
    taglineSpacingInput.addEventListener('input', (e) => { state.taglineSpacing = parseFloat(e.target.value); updateRenders(); });
    taglineSizeInput.addEventListener('input', (e) => { state.taglineSize = parseFloat(e.target.value); updateRenders(); });

    // Zoom Controls
    document.getElementById('zoom-in').addEventListener('click', () => {
      if (state.zoom < 5) { state.zoom += 0.4; updateRenders(); }
    });
    document.getElementById('zoom-out').addEventListener('click', () => {
      if (state.zoom > 0.8) { state.zoom -= 0.4; updateRenders(); }
    });

    // Toggle Inspector Background (Light/Dark)
    document.getElementById('toggle-bg').addEventListener('click', () => {
      state.isDarkInspect = !state.isDarkInspect;
      if (state.isDarkInspect) {
        inspectorCanvas.classList.remove('checkered-bg');
        inspectorCanvas.classList.add('dark-checkered-bg');
      } else {
        inspectorCanvas.classList.remove('dark-checkered-bg');
        inspectorCanvas.classList.add('checkered-bg');
      }
    });

    // Toast Notification helper
    function showToast(msg) {
      const toast = document.getElementById('toast');
      document.getElementById('toast-msg').innerText = msg;
      toast.classList.remove('opacity-0', 'translate-y-4', 'pointer-events-none');
      toast.classList.add('opacity-100', 'translate-y-0');
      setTimeout(() => {
        toast.classList.remove('opacity-100', 'translate-y-0');
        toast.classList.add('opacity-0', 'translate-y-4', 'pointer-events-none');
      }, 2400);
    }

    // Clipboard Copy
    document.getElementById('copy-code-btn').addEventListener('click', () => {
      const code = generateSVGString();
      const textarea = document.createElement('textarea');
      textarea.value = code;
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand('copy');
      document.body.removeChild(textarea);
      showToast('SVG Code copied to clipboard!');
    });

    // SVG File Download
    document.getElementById('download-svg-btn').addEventListener('click', () => {
      const code = generateSVGString();
      const blob = new Blob([code], { type: 'image/svg+xml' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'nutridupe-logo.svg';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      showToast('Downloaded nutridupe-logo.svg!');
    });

    // Reset Defaults
    document.getElementById('reset-defaults-btn').addEventListener('click', () => {
      state.stemWidth = 9;
      state.rCurve = 16;
      state.rExt = 18;
      state.riGap = 8;
      state.leafScale = 1.1;
      state.leafY = -2;
      state.textColor = "#0F172A";
      state.leafColor = "#10B981";
      state.taglineSpacing = 3.5;
      state.taglineSize = 11;
      state.zoom = 2.2;

      stemWidthInput.value = 9;
      rCurveInput.value = 16;
      rExtInput.value = 18;
      riGapInput.value = 8;
      leafScaleInput.value = 1.1;
      leafYInput.value = -2;
      textColorInput.value = "#0F172A";
      leafColorInput.value = "#10B981";
      taglineSpacingInput.value
